1	import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
2	import { createRequire } from 'node:module';
3	import { charIn, createRegExp, exactly, global, maybe, oneOrMore, whitespace, wordChar } from 'magic-regexp';
4	import * as path from 'pathe';
5	
6	/**
7	 * Reusable create-react-app compatibility capabilities for a Vite build.
8	 *
9	 * Every export here is application agnostic: the shapes handled are the ones
10	 * create-react-app itself defines (HTML template placeholders, `process.env`
11	 * inlining, the ambient `global` identifier, webpack's automatic Node core
12	 * module polyfills, webpack tilde specifiers, and the copied public directory).
13	 * No capability branches on an application name, revision, or source string.
14	 */
15	
16	export type CraEnvironment = Readonly<Record<string, string>>;
17	
18	const templatePlaceholder = createRegExp(
19		exactly('%').and(oneOrMore(wordChar).groupedAs('key')).and('%'),
20		[global],
21	);
22	
23	const tildePrefixedCssImport = createRegExp(
24		exactly('@import')
25			.and(oneOrMore(whitespace))
26			.and(maybe(exactly('url').and(maybe(whitespace)).and('(').and(maybe(whitespace))))
27			.and(charIn(`'"`))
28			.and('~'),
29		[global],
30	);
31	
32	const closingBodyTag = createRegExp(
33		exactly('<').and(maybe(whitespace)).and('/').and(maybe(whitespace)).and('body'),
34	);
35	
36	export function compareUtf16CodeUnits(left: string, right: string): number {
37		if (left === right) return 0;
38		return left < right ? -1 : 1;
39	}
40	
41	/**
42	 * Replace `%KEY%` template placeholders the way create-react-app's
43	 * InterpolateHtmlPlugin does: only keys present in the environment are
44	 * substituted, and unknown placeholders are preserved verbatim.
45	 */
46	export function substituteCraTemplatePlaceholders(
47		template: string,
48		environment: CraEnvironment,
49	): string {
50		return template.replace(templatePlaceholder, (match: string, key: string) =>
51			Object.hasOwn(environment, key) ? (environment[key] as string) : match,
52		);
53	}
54	
55	export type CraEntryDocumentOptions = Readonly<{
56		template: string;
57		entryModule: string;
58		environment?: CraEnvironment;
59		bootstrapModules?: readonly string[];
60	}>;
61	
62	/**
63	 * Turn a create-react-app `public/index.html` template into a Vite entry
64	 * document: placeholders are substituted and the application entry is injected
65	 * as a module script immediately before the closing body tag.
66	 *
67	 * `bootstrapModules` are imported by inline module scripts placed ahead of the
68	 * application entry. Module scripts evaluate in document order, so a bootstrap
69	 * listed here runs before the first application module — the position webpack
70	 * used for the bindings it injected into every module. Omitting the option
71	 * leaves the document byte-identical to one produced without it.
72	 */
73	export function craEntryDocument(options: CraEntryDocumentOptions): string {
74		const substituted = substituteCraTemplatePlaceholders(
75			options.template,
76			options.environment ?? {},
77		);
78		const bootstrap = (options.bootstrapModules ?? [])
79			.map((module) => `<script type="module">import ${JSON.stringify(module)};</script>\n  `)
80			.join('');
81		const script = `${bootstrap}<script type="module" src="${options.entryModule}"></script>`;
82		const match = closingBodyTag.exec(substituted);
83		if (!match) return `${substituted}${substituted.endsWith('\n') ? '' : '\n'}${script}\n`;
84		return `${substituted.slice(0, match.index)}  ${script}\n  ${substituted.slice(match.index)}`;
85	}
86	
87	/**
88	 * Build the `define` map create-react-app's DefinePlugin provides: one entry per
89	 * environment key plus the whole `process.env` object for dynamic access.
90	 */
91	export function craProcessEnvironmentDefines(
92		environment: CraEnvironment,
93	): Readonly<Record<string, string>> {
94		const keys = Object.keys(environment).sort(compareUtf16CodeUnits);
95		const sorted = Object.fromEntries(keys.map((key) => [key, environment[key] as string]));
96		return Object.freeze({
97			...Object.fromEntries(
98				keys.map((key) => [`process.env.${key}`, JSON.stringify(environment[key])]),
99			),
100			'process.env': JSON.stringify(sorted),
101		});
102	}
103	
104	/**
105	 * The ambient identifier webpack 4 provides to every module it bundles for the
106	 * browser. webpack's runtime declares `global` itself (its `node.global`
107	 * option defaults to `true` on the webpack 4 line create-react-app 3 and 4
108	 * pin), so a dependency written against Node's `global` keeps working inside a
109	 * webpack browser bundle. Vite emits no such declaration: the same dependency
110	 * reaches the browser with a free `global` reference and throws
111	 * `ReferenceError: global is not defined` on first evaluation. Mapping the
112	 * identifier onto `globalThis` restores exactly the binding webpack supplied
113	 * and nothing else — it is a compile-time substitution of one free identifier,
114	 * so member accesses, property keys and locally bound `global` names are left
115	 * alone, and modules that never mention it emit byte-identical output.
116	 */
117	export function craGlobalIdentifierDefines(): Readonly<Record<string, string>> {
118		return Object.freeze({ global: 'globalThis' });
119	}
120	
121	export type CraDefineConfig = Readonly<{ define: Readonly<Record<string, string>> }>;
122	export type CraDefinePlugin = Readonly<{ name: string; config(): CraDefineConfig }>;
123	
124	/**
125	 * Contribute the webpack `global` binding as a Vite `define` entry. It is
126	 * contributed through the plugin's own configuration rather than asked of every
127	 * consumer, so any build that adopts the create-react-app adapter inherits the
128	 * ambient identifier its bundler used to provide.
129	 */
130	export function createCraGlobalIdentifierPlugin(): CraDefinePlugin {
131		return {
132			name: 'versionless-cra-global-identifier',
133			config() {
134				return { define: craGlobalIdentifierDefines() };
135			},
136		};
137	}
138	
139	/**
140	 * webpack 4's automatic Node core module resolution table, reproduced verbatim
141	 * from the `node-libs-browser` package webpack 4 depends on.
142	 *
143	 * webpack 4 resolved a bare `require('stream')` in browser builds to a browser
144	 * shim package rather than to a Node builtin, so dependencies written against
145	 * Node's standard library kept working unchanged inside a create-react-app
146	 * bundle. Vite performs no such substitution: it treats every Node builtin as
147	 * an external and emits a `__vite-browser-external` stub, so the same
148	 * `require('stream')` yields `undefined` and the first dependency that reads a
149	 * property off it fails at load — `readable-stream` 1.x, for instance, throws
150	 * `TypeError: Object prototype may only be an Object or null: undefined` from
151	 * `inherits`.
152	 *
153	 * The entries `node-libs-browser` maps to `null` (`fs`, `net`, `child_process`,
154	 * `dns`, `dgram`, `tls`, `cluster`, `module`, `readline`, `repl`) are absent
155	 * here on purpose: webpack emitted an empty module for those and Vite's own
156	 * browser-external stub already occupies that role, so nothing is claimed about
157	 * them.
158	 */
159	export const craWebpackNodeCoreShimSpecifiers: Readonly<Record<string, string>> = Object.freeze({
160		_stream_duplex: 'readable-stream/duplex.js',
161		_stream_passthrough: 'readable-stream/passthrough.js',
162		_stream_readable: 'readable-stream/readable.js',
163		_stream_transform: 'readable-stream/transform.js',
164		_stream_writable: 'readable-stream/writable.js',
165		assert: 'assert/',
166		buffer: 'buffer/',
167		console: 'console-browserify',
168		constants: 'constants-browserify',
169		crypto: 'crypto-browserify',
170		domain: 'domain-browser',
171		events: 'events/',
172		http: 'stream-http',
173		https: 'https-browserify',
174		os: 'os-browserify/browser.js',
175		path: 'path-browserify',
176		process: 'process/browser.js',
177		punycode: 'punycode/',
178		querystring: 'querystring-es3/',
179		stream: 'stream-browserify',
180		string_decoder: 'string_decoder/',
181		sys: 'util/util.js',
182		timers: 'timers-browserify',
183		tty: 'tty-browserify',
184		url: 'url/',
185		util: 'util/util.js',
186		vm: 'vm-browserify',
187		zlib: 'browserify-zlib',
188	});
189	
190	const nodeProtocolPrefix = 'node:';
191	
192	/**
193	 * The core module name a bare import specifier asks for, or `null` when the
194	 * specifier is not one webpack 4 polyfilled. Both `stream` and `node:stream`
195	 * name the same module.
196	 */
197	export function craNodeCoreModuleName(source: string): string | null {
198		const bare = source.startsWith(nodeProtocolPrefix)
199			? source.slice(nodeProtocolPrefix.length)
200			: source;
201		return Object.hasOwn(craWebpackNodeCoreShimSpecifiers, bare) ? bare : null;
202	}
203	
204	/** The package a shim specifier belongs to, for a diagnosable failure. */
205	export function craNodeCoreShimPackage(specifier: string): string {
206		const segments = specifier.split('/').filter((segment) => segment.length > 0);
207		const first = segments[0] ?? specifier;
208		return first.startsWith('@') && segments.length > 1 ? `${first}/${segments[1] as string}` : first;
209	}
210	
211	/** Resolve a bare specifier to a file, the way a require from a directory would. */
212	export type CraModuleResolver = (specifier: string) => string;
213	
214	/**
215	 * A resolver that searches the application's own dependency closure, which is
216	 * what webpack 4 did: the shim packages arrive through react-scripts' transitive
217	 * closure and are resolved against the application being compiled, never against
218	 * the build tool's own installation.
219	 */
220	export function craApplicationModuleResolver(applicationRoot: string): CraModuleResolver {
221		const applicationRequire = createRequire(path.join(path.resolve(applicationRoot), 'package.json'));
222		return (specifier) => applicationRequire.resolve(specifier);
223	}
224	
225	/**
226	 * Resolve one Node core module to its webpack 4 browser shim. A shim missing
227	 * from the application's closure is a hard failure naming the module, the
228	 * package webpack would have used, and where it was searched — never a silent
229	 * stub, because a silent stub is the defect this capability exists to remove.
230	 */
231	export function resolveCraNodeCoreModule(
232		module: string,
233		resolver: CraModuleResolver,
234		origin: string,
235	): string {
236		const specifier = craWebpackNodeCoreShimSpecifiers[module];
237		if (specifier === undefined)
238			throw new Error(`Node core module "${module}" has no webpack 4 browser shim`);
239		try {
240			return resolver(specifier);
241		} catch {
242			throw new Error(
243				`create-react-app compatibility: this build imports the Node core module "${module}", ` +
244					`which webpack 4 resolved to the browser shim "${specifier}". The package ` +
245					`"${craNodeCoreShimPackage(specifier)}" is absent from the application dependency ` +
246					`closure at ${origin}, so "${module}" cannot be provided and would reach the browser ` +
247					`as an undefined stub. Install it into that closure or drop the import.`,
248			);
249		}
250	}
251	
252	/**
253	 * The identifiers webpack 4 injected into every module it bundled for the
254	 * browser, and the core module each one is sourced from. `node.process`,
255	 * `node.Buffer` and `node.setImmediate` all default to `true` on the webpack 4
256	 * line create-react-app pins, so a dependency that reads `process.nextTick`,
257	 * constructs a `Buffer`, or calls `setImmediate` keeps working with no import.
258	 * Vite injects nothing, so those same references reach the browser free and the
259	 * first one evaluated throws `ReferenceError: process is not defined`.
260	 *
261	 * The bootstrap module below installs exactly these bindings, sourced from the
262	 * same shim packages the resolution table names, and it is evaluated before the
263	 * application entry. `global` is not listed: it is already supplied as a
264	 * compile-time substitution by the global identifier capability.
265	 */
266	export const craWebpackNodeInjectedGlobals: Readonly<Record<string, string>> = Object.freeze({
267		Buffer: 'buffer',
268		clearImmediate: 'timers',
269		process: 'process',
270		setImmediate: 'timers',
271	});
272	
273	/** The module id an entry document imports to install webpack's injected globals. */
274	export const craNodeGlobalsModuleId = 'virtual:versionless-cra-node-globals';
275	
276	const resolvedNodeGlobalsModuleId = `\0${craNodeGlobalsModuleId}`;
277	
278	/**
279	 * Source for the injected-globals bootstrap, built from files already resolved
280	 * out of the application's own closure. Assignment is conditional so a host that
281	 * genuinely provides one of these names keeps it.
282	 */
283	export function craNodeGlobalsBootstrapSource(
284		files: Readonly<{ process: string; buffer: string; timers: string }>,
285	): string {
286		return [
287			`import craProcess from ${JSON.stringify(files.process)};`,
288			`import craBuffer from ${JSON.stringify(files.buffer)};`,
289			`import craTimers from ${JSON.stringify(files.timers)};`,
290			'globalThis.process ??= craProcess;',
291			'globalThis.Buffer ??= craBuffer.Buffer;',
292			'globalThis.setImmediate ??= craTimers.setImmediate;',
293			'globalThis.clearImmediate ??= craTimers.clearImmediate;',
294			'',
295		].join('\n');
296	}
297	
298	export type CraResolvedRootConfig = Readonly<{ root: string }>;
299	export type CraNodeCoreModulePlugin = Readonly<{
300		name: string;
301		enforce: 'pre';
302		configResolved(config: CraResolvedRootConfig): void;
303		resolveId(source: string): string | null;
304		load(id: string): string | null;
305	}>;
306	
307	export type CraNodeCoreModuleOptions = Readonly<{ applicationRoot?: string }>;
308	
309	/**
310	 * Provide webpack 4's Node core module polyfills to a Vite build. Resolution is
311	 * lazy — a core module is only resolved when the module graph actually asks for
312	 * it — so an application that imports nothing from the standard library pays
313	 * nothing and cannot be failed by a shim it never needed.
314	 */
315	export function createCraNodeCoreModulePlugin(
316		options: CraNodeCoreModuleOptions = {},
317	): CraNodeCoreModulePlugin {
318		let applicationRoot = options.applicationRoot ?? '';
319		let resolver: CraModuleResolver | null = null;
320		const resolve = (module: string): string => {
321			if (!applicationRoot)
322				throw new Error('CRA node core module resolution has no application root');
323			resolver ??= craApplicationModuleResolver(applicationRoot);
324			return resolveCraNodeCoreModule(module, resolver, applicationRoot);
325		};
326		return {
327			name: 'versionless-cra-node-core-modules',
328			enforce: 'pre',
329			configResolved(config) {
330				if (!options.applicationRoot) applicationRoot = config.root;
331				resolver = null;
332			},
333			resolveId(source) {
334				if (source === craNodeGlobalsModuleId) return resolvedNodeGlobalsModuleId;
335				const module = craNodeCoreModuleName(source);
336				return module === null ? null : resolve(module);
337			},
338			load(id) {
339				if (id !== resolvedNodeGlobalsModuleId) return null;
340				return craNodeGlobalsBootstrapSource({
341					buffer: resolve('buffer'),
342					process: resolve('process'),
343					timers: resolve('timers'),
344				});
345			},
346		};
347	}
348	
349	/**
350	 * Rewrite webpack's tilde-prefixed bare specifiers in CSS `@import` rules to
351	 * plain bare specifiers, which Vite resolves through node resolution.
352	 */
353	export function rewriteWebpackTildeCssImports(code: string): string {
354		return code.replace(tildePrefixedCssImport, (match: string) => match.slice(0, -1));
355	}
356	
357	function pathWithoutQuery(id: string): string {
358		const index = id.indexOf('?');
359		return index === -1 ? id : id.slice(0, index);
360	}
361	
362	export type CraTransformResult = Readonly<{ code: string; map: null }>;
363	export type CraTransformPlugin = Readonly<{
364		name: string;
365		enforce: 'pre';
366		transform(code: string, id: string): CraTransformResult | null;
367	}>;
368	
369	export function createCraTildeCssImportPlugin(): CraTransformPlugin {
370		return {
371			name: 'versionless-cra-tilde-css-import',
372			enforce: 'pre',
373			transform(code, id) {
374				if (path.extname(pathWithoutQuery(id)) !== '.css') return null;
375				const rewritten = rewriteWebpackTildeCssImports(code);
376				return rewritten === code ? null : { code: rewritten, map: null };
377			},
378		};
379	}
380	
381	async function filesBelow(directory: string): Promise<string[]> {
382		const files: string[] = [];
383		for (const entry of await readdir(directory, { withFileTypes: true })) {
384			const item = path.join(directory, entry.name);
385			if (entry.isDirectory()) files.push(...(await filesBelow(item)));
386			else if (entry.isFile()) files.push(item);
387		}
388		return files;
389	}
390	
391	/**
392	 * The create-react-app public directory inventory: every file below the
393	 * directory except the excluded template, as sorted relative POSIX paths.
394	 */
395	export async function craPublicAssetPaths(
396		directory: string,
397		exclude: readonly string[] = [],
398	): Promise<readonly string[]> {
399		const excluded = new Set(exclude);
400		return (await filesBelow(directory))
401			.map((file) => path.relative(directory, file).split(path.sep).join('/'))
402			.filter((file) => !excluded.has(file))
403			.sort(compareUtf16CodeUnits);
404	}
405	
406	export type CraResolvedBuildConfig = Readonly<{ build: Readonly<{ outDir: string }> }>;
407	export type CraOutputPlugin = Readonly<{
408		name: string;
409		configResolved(config: CraResolvedBuildConfig): void;
410		closeBundle: Readonly<{ order: 'post'; sequential: true; handler(): Promise<void> }>;
411	}>;
412	
413	export type CraPublicDirectoryOptions = Readonly<{
414		directory: string;
415		exclude?: readonly string[];
416	}>;
417	
418	/**
419	 * Copy the create-react-app public directory into the build output the way
420	 * `react-scripts build` does, excluding the HTML template that becomes the
421	 * bundled entry document.
422	 */
423	export function createCraPublicDirectoryPlugin(
424		options: CraPublicDirectoryOptions,
425	): CraOutputPlugin {
426		let outputDirectory = '';
427		return {
428			name: 'versionless-cra-public-directory',
429			configResolved(config) {
430				outputDirectory = path.resolve(config.build.outDir);
431			},
432			closeBundle: {
433				order: 'post',
434				sequential: true,
435				async handler() {
436					if (!outputDirectory) throw new Error('CRA public directory outDir is unresolved');
437					for (const file of await craPublicAssetPaths(
438						options.directory,
439						options.exclude ?? [],
440					)) {
441						const destination = path.join(outputDirectory, file);
442						await mkdir(path.dirname(destination), { recursive: true });
443						await writeFile(destination, await readFile(path.join(options.directory, file)));
444					}
445				},
446			},
447		};
448	}
449	
450	export type CraViteAdapterOptions = Readonly<{
451		publicDirectory: string;
452		templateFile?: string;
453		applicationRoot?: string;
454	}>;
455	
456	export type CraViteAdapterPlugins = readonly [
457		CraTransformPlugin,
458		CraNodeCoreModulePlugin,
459		CraDefinePlugin,
460		CraOutputPlugin,
461	];
462	
463	/**
464	 * The create-react-app compatibility plugin set: tilde CSS specifier rewriting,
465	 * webpack's automatic Node core module polyfills, the ambient `global`
466	 * identifier, plus public directory replication.
467	 */
468	export function createCraViteAdapter(options: CraViteAdapterOptions): CraViteAdapterPlugins {
469		return [
470			createCraTildeCssImportPlugin(),
471			createCraNodeCoreModulePlugin(
472				options.applicationRoot === undefined ? {} : { applicationRoot: options.applicationRoot },
473			),
474			createCraGlobalIdentifierPlugin(),
475			createCraPublicDirectoryPlugin({
476				directory: options.publicDirectory,
477				exclude: [options.templateFile ?? 'index.html'],
478			}),
479		];
480	}
