import { mkdir, mkdtemp, writeFile, rm, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { createContext, runInContext } from 'node:vm';
import * as path from 'pathe';
import { build } from 'vite';
import { createCraSloppyCommonJsGlobalsPlugin } from '../../packages/frameworks/react/src/react-cra-vite-adapter.ts';

const root = await mkdtemp(path.join(tmpdir(), 'vl-sloppy-'));
const dep = path.join(root, 'node_modules/legacy-dep');
const reader = path.join(root, 'node_modules/legacy-reader');
await mkdir(dep, { recursive: true });
await mkdir(reader, { recursive: true });
await writeFile(path.join(root, 'package.json'), JSON.stringify({ name: 'p', version: '0.0.0' }));
await writeFile(path.join(dep, 'package.json'), JSON.stringify({ name: 'legacy-dep', version: '1.0.0', main: 'index.js' }));
await writeFile(path.join(dep, 'index.js'), "function h(s){ txt = ''; for (var i=0;i<s.length;i++) txt += s[i]; return txt; }\nmodule.exports = { probe: h('abc') };\n");
await writeFile(path.join(reader, 'package.json'), JSON.stringify({ name: 'legacy-reader', version: '1.0.0', main: 'index.js' }));
await writeFile(path.join(reader, 'index.js'), "module.exports = { seen: typeof txt === 'string' ? txt : null };\n");
await writeFile(path.join(root, 'entry.js'), "import dep from 'legacy-dep';\nimport reader from 'legacy-reader';\nexport const probe = { dep, reader };\n");
const records: unknown[] = [];
for (const withAdapter of [false, true]) {
  const outDir = path.join(root, withAdapter ? 'dist-a' : 'dist-c');
  await build({ root, logLevel: 'silent', plugins: withAdapter ? [createCraSloppyCommonJsGlobalsPlugin({ observe: (r) => records.push(r) })] : [], build: { outDir, minify: false, lib: { entry: path.join(root, 'entry.js'), formats: ['iife'], name: 'probe', fileName: () => 'probe.js' } } });
  const code = await readFile(path.join(outDir, 'probe.js'), 'utf8');
  const ctx = createContext({});
  try { runInContext(code, ctx); console.log(withAdapter ? 'ADAPTED' : 'CONTROL', 'ok', JSON.stringify((ctx as any).probe.probe)); }
  catch (e) { console.log(withAdapter ? 'ADAPTED' : 'CONTROL', 'THREW', String(e)); }
}
console.log('records', JSON.stringify(records.map((r: any) => ({ id: path.relative(root, r.id), names: r.names }))));
await rm(root, { recursive: true, force: true });
